function evidence = f90_xrobo06_extract_reference_evidence(modelPath, outputDir, officialScenarios, evaluatorAssetRoot)
%F90_XROBO06_EXTRACT_REFERENCE_EVIDENCE One-session four-scenario replay.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
    officialScenarios (1,1) string
    evaluatorAssetRoot (1,1) string
end
assert(isfile(officialScenarios), "SimuVerity:F90:XROBO06:OfficialScenarios", ...
    "Official scenarios are missing.");
assert(isfolder(evaluatorAssetRoot), "SimuVerity:F90:XROBO06:ReferenceAssetRoot", ...
    "Evaluator asset root is missing.");
referenceRoot = string(fileparts(modelPath));
official = jsondecode(fileread(officialScenarios));
modelFile = modelPath;
libraryFile = fullfile(referenceRoot, "sm_humanoid_walker_lib.slx");
agentFile = fullfile(referenceRoot, "sm_humanoid_walker_saved_agent.mat");
parameterFile = fullfile(referenceRoot, "sm_humanoid_walker_rl_parameters.m");
assert(strcmpi(localFilePresence(modelFile), string("present")), ...
    "SimuVerity:F90:XROBO06:ModelBinding", "Pinned root-model binding mismatch.");
assert(strcmpi(localFilePresence(libraryFile), ...
    "present"), ...
    "SimuVerity:F90:XROBO06:LibraryBinding", "Pinned linked-library binding mismatch.");
assert(strcmpi(localFilePresence(agentFile), ...
    "present"), ...
    "SimuVerity:F90:XROBO06:PolicyBinding", "Pinned saved-policy binding mismatch.");
assert(strcmpi(localFilePresence(parameterFile), ...
    "present"), ...
    "SimuVerity:F90:XROBO06:ParameterBinding", "Pinned parameter-script binding mismatch.");

generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
assert(strlength(generationRunId) > 0, "SimuVerity:F90:XROBO06:GenerationRunId", ...
    "SIMUVERITY_GENERATION_RUN_ID is required.");
outDir = outputDir;
assert(~isfolder(outDir), "SimuVerity:F90:XROBO06:OutputReuse", ...
    "Evidence output already exists for GenerationRunId %s.", generationRunId);
mkdir(outDir);

cacheDir = string(getenv("SIMULINK_CACHE_FOLDER"));
codegenDir = string(getenv("SIMULINK_CODEGEN_FOLDER"));
assert(strlength(cacheDir) > 0 && strlength(codegenDir) > 0, ...
    "SimuVerity:F90:XROBO06:Isolation", ...
    "Isolated cache and codegen folders are required.");
Simulink.fileGenControl("set", "CacheFolder", cacheDir, ...
    "CodeGenFolder", codegenDir, "createDir", true);
set(groot, "defaultFigureVisible", "off");
addpath(referenceRoot, "-begin");
originalDirectory = pwd;
directoryCleanup = onCleanup(@() cd(originalDirectory)); %#ok<NASGU>
cd(referenceRoot);

evidence = struct( ...
    "schema", "simuverity.f90-xrobo06-evidence.v1", ...
    "task_id", "F90-XROBO-06", ...
    "reference_substantive_modifications", 0, ...
    "extraction_only", true, ...
    "contains_score_decisions", false, ...
    "load_pass", false, ...
    "update_pass", false, ...
    "compile_pass", false, ...
    "nominal_smoke_pass", false, ...
    "static_audit", struct, ...
    "scenarios", struct([]), ...
    "errors", struct, ...
    "started_at", localNow, ...
    "runtime", struct( ...
        "generation_run_id", generationRunId, ...
        "matlab_release", string(version("-release")), ...
        "mcp_port", string(getenv("SIMUVERITY_MCP_PORT")), ...
        "matlab_prefdir", string(getenv("MATLAB_PREFDIR")), ...
        "cache", cacheDir, ...
        "codegen", codegenDir));

model = "";
try
    run(parameterFile);
    baselineParams = params;
    loadedPolicy = load(agentFile);
    assert(isfield(loadedPolicy, "saved_agent"), ...
        "SimuVerity:F90:XROBO06:SavedPolicy", ...
        "Pinned policy file does not contain saved_agent.");
    assignin("base", "f90_reference_agent", loadedPolicy.saved_agent);
    assignin("base", "params", baselineParams);

    load_system(libraryFile);
    modelHandle = load_system(modelFile);
    model = string(get_param(modelHandle, "Name"));
    cleanup = onCleanup(@() localCloseModels(model)); %#ok<NASGU>
    evidence.load_pass = true;
    agentBlock = model + "/RL Agent";
    set_param(agentBlock, "Agent", "f90_reference_agent");
    set_param(model, ...
        "ReturnWorkspaceOutputs", "on", ...
        "SignalLogging", "on", ...
        "SignalLoggingName", "logsout", ...
        "FastRestart", "off");

    tapPlan = localInstallSelectorInputs(model);
    set_param(model, "SimulationCommand", "update");
    localCompleteMeasurementTaps(model, tapPlan);
    localApplyScenario(model, baselineParams, official.scenarios(1));
    set_param(model, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    evidence.compile_pass = true;
    evidence.static_audit = localStaticAudit(model);

    localApplyScenario(model, baselineParams, official.scenarios(1));
    set_param(model, "StopTime", "0.5");
    smoke = sim(model, "ReturnWorkspaceOutputs", "on");
    localValidateSmoke(smoke);
    evidence.nominal_smoke_pass = true;
    clear smoke

    rows = repmat(localEmptyScenario, numel(official.scenarios), 1);
    for k = 1:numel(official.scenarios)
        scenario = official.scenarios(k);
        rows(k).id = string(scenario.id);
        rows(k).requested_inputs = scenario;
        try
            localApplyScenario(model, baselineParams, scenario);
            set_param(model, "StopTime", ...
                sprintf("%.17g", double(scenario.stop_time_s)));
            started = tic;
            simOut = sim(model, "ReturnWorkspaceOutputs", "on");
            rows(k).simulation_wall_clock_s = toc(started);
            outputs = localExtractOutputs(simOut, ...
                double(scenario.stop_time_s), ...
                double(baselineParams.simulation.Ts));
            rows(k) = localFinalizeScenario(rows(k), outputs, ...
                double(scenario.stop_time_s));
            clear simOut
        catch ME
            rows(k).error = localError(ME);
        end
    end
    evidence.scenarios = rows;
catch ME
    evidence.errors.session = localError(ME);
end

localCloseModels(model);
evidence.model_closed_without_save = ~bdIsLoaded(model);
evidence.root_model_file_presence_after = localFilePresence(modelFile);
evidence.library_file_presence_after = localFilePresence(libraryFile);
evidence.binding_preserved = ...
    strcmpi(evidence.root_model_file_presence_after, ...
        string("present")) && ...
    strcmpi(evidence.library_file_presence_after, ...
        "present");
evidence.finished_at = localNow;
validCount = 0;
if ~isempty(evidence.scenarios)
    validCount = sum([evidence.scenarios.valid]);
end
evidence.EVIDENCE_COMPLETE = evidence.load_pass && evidence.update_pass && ...
    evidence.compile_pass && evidence.nominal_smoke_pass && ...
    evidence.binding_preserved && numel(evidence.scenarios) == numel(official.scenarios) && ...
    validCount == numel(official.scenarios);
evidencePath = fullfile(outDir, "evidence.json");
localWriteJson(evidencePath, evidence);
fprintf("F90_XROBO06_EVIDENCE load=%d update=%d compile=%d smoke=%d valid=%d/%d binding=%d path=%s\n", ...
    evidence.load_pass, evidence.update_pass, evidence.compile_pass, ...
    evidence.nominal_smoke_pass, validCount, ...
    numel(evidence.scenarios), evidence.binding_preserved, evidencePath);
end

function plan = localInstallSelectorInputs(model)
environment = model + "/Learning Environment";
physical = environment + "/Physical Model";
plan = struct;
plan.contact = localAddBusSelector(environment, physical, 1, ...
    "F90 Contact Selector", ["rightContact", "leftContact"]);
plan.torso = localAddBusSelector(environment, physical, 2, ...
    "F90 Torso Selector", ...
    ["qx", "qy", "qz", "wx", "wy", "wz", ...
     "x", "dz", "vx", "vy", "vz"]);
plan.joint = localAddBusSelector(environment, physical, 3, ...
    "F90 Joint Selector", [ ...
    "signal1.signal1.rhTheta", "signal1.signal1.rhThetaDot", ...
    "signal1.signal2.rkTheta", "signal1.signal2.rkThetaDot", ...
    "signal1.signal3.raTheta", "signal1.signal3.raThetaDot", ...
    "signal2.signal1.lhTheta", "signal2.signal1.lhThetaDot", ...
    "signal2.signal2.lkTheta", "signal2.signal2.lkThetaDot", ...
    "signal2.signal3.laTheta", "signal2.signal3.laThetaDot"]);
plan.torque = localAddBusSelector(environment, ...
    environment + "/Joint Control", 1, "F90 Torque Selector", [ ...
    "Right Hip Frontal Torque", "Right Knee Torque", ...
    "Right Ankle Torque", "Left Hip Frontal Torque", ...
    "Left Knee Torque", "Left Ankle Torque"]);
end

function plan = localAddBusSelector(parent, source, port, name, signals)
selector = parent + "/" + name;
assert(getSimulinkBlockHandle(selector) < 0, ...
    "SimuVerity:F90:XROBO06:TapCollision", ...
    "Temporary selector already exists: %s", selector);
add_block("simulink/Signal Routing/Bus Selector", selector, ...
    "OutputSignals", strjoin(signals, ","));
sourcePorts = get_param(source, "PortHandles");
selectorPorts = get_param(selector, "PortHandles");
assert(sourcePorts.Outport(port) > 0 && selectorPorts.Inport(1) > 0, ...
    "SimuVerity:F90:XROBO06:TapPort", "A required bus source port is missing.");
add_line(parent, sourcePorts.Outport(port), selectorPorts.Inport(1), ...
    "autorouting", "on");
plan = struct("parent", parent, "selector", selector, ...
    "signals", signals);
end

function localCompleteMeasurementTaps(model, plan)
localCompleteBusTap(plan.contact, "f90_foot_contact");
localCompleteBusTap(plan.torso, "f90_torso_state");
localCompleteBusTap(plan.joint, "f90_joint_state");
localCompleteBusTap(plan.torque, "f90_joint_torque");

environment = model + "/Learning Environment";
dataProcessing = environment + "/Data Processing";
localDirectTap(model, model + "/RL Agent", 1, "f90_control_action");
localDirectTap(environment, environment + "/Physical Model", 4, ...
    "f90_forward_position");
localDirectTap(dataProcessing, dataProcessing + "/Calculate Power", 1, ...
    "f90_power");
localDirectTap(dataProcessing, dataProcessing + "/Calculate Reward", 1, ...
    "f90_reward");
localDirectTap(dataProcessing, dataProcessing + "/Check if Done1", 1, ...
    "f90_done");
end

function localCompleteBusTap(plan, variable)
mux = plan.parent + "/F90 " + variable + " Mux";
sink = plan.parent + "/F90 " + variable + " Tap";
add_block("simulink/Signal Routing/Mux", mux, ...
    "Inputs", sprintf("%d", numel(plan.signals)));
add_block("simulink/Sinks/To Workspace", sink, ...
    "VariableName", variable, ...
    "SaveFormat", "Timeseries", ...
    "MaxDataPoints", "inf");
selectorPorts = get_param(plan.selector, "PortHandles");
muxPorts = get_param(mux, "PortHandles");
sinkPorts = get_param(sink, "PortHandles");
assert(numel(selectorPorts.Outport) == numel(plan.signals), ...
    "SimuVerity:F90:XROBO06:SelectorPorts", ...
    "Compiled selector %s has an unexpected number of outputs.", ...
    plan.selector);
for k = 1:numel(plan.signals)
    add_line(plan.parent, selectorPorts.Outport(k), ...
        muxPorts.Inport(k), "autorouting", "on");
end
add_line(plan.parent, muxPorts.Outport(1), sinkPorts.Inport(1), ...
    "autorouting", "on");
end

function localDirectTap(parent, source, port, variable)
sink = parent + "/F90 " + variable + " Tap";
assert(getSimulinkBlockHandle(sink) < 0, ...
    "SimuVerity:F90:XROBO06:TapCollision", ...
    "Temporary measurement tap already exists: %s", sink);
add_block("simulink/Sinks/To Workspace", sink, ...
    "VariableName", variable, ...
    "SaveFormat", "Timeseries", ...
    "MaxDataPoints", "inf");
sourcePorts = get_param(source, "PortHandles");
sinkPorts = get_param(sink, "PortHandles");
assert(sourcePorts.Outport(port) > 0 && sinkPorts.Inport(1) > 0, ...
    "SimuVerity:F90:XROBO06:TapPort", ...
    "A required direct measurement source port is missing.");
add_line(parent, sourcePorts.Outport(port), sinkPorts.Inport(1), ...
    "autorouting", "on");
end

function localApplyScenario(model, baseline, scenario)
params = baseline;
frictionScale = double(scenario.FootFrictionScale);
torqueScale = double(scenario.TorqueLimitScale);
params.contact.staticFriction = ...
    baseline.contact.staticFriction * frictionScale;
params.contact.dynamicFriction = ...
    baseline.contact.dynamicFriction * frictionScale;
params.torqueLimits.hipFrontal = ...
    baseline.torqueLimits.hipFrontal * torqueScale;
params.torqueLimits.knee = baseline.torqueLimits.knee * torqueScale;
params.torqueLimits.ankle = baseline.torqueLimits.ankle * torqueScale;
params.simulation.initialHeight = double(scenario.InitialHeight_m);
params.simulation.Tf = double(scenario.stop_time_s);
assignin("base", "params", params);
assignin("base", "FootFrictionScale", frictionScale);
assignin("base", "TorqueLimitScale", torqueScale);
assignin("base", "InitialHeight_m", ...
    double(scenario.InitialHeight_m));
modelWorkspace = get_param(model, "ModelWorkspace");
assignin(modelWorkspace, "params", params);
end

function localValidateSmoke(simOut)
required = { ...
    "f90_foot_contact", 2; ...
    "f90_torso_state", 11; ...
    "f90_joint_state", 12; ...
    "f90_control_action", 6; ...
    "f90_joint_torque", 6; ...
    "f90_forward_position", 1; ...
    "f90_power", 1; ...
    "f90_reward", 1; ...
    "f90_done", 1};
for k = 1:size(required, 1)
    localWorkspaceTimeseries(simOut, required{k, 1}, required{k, 2});
end
end

function outputs = localExtractOutputs(simOut, stopTime, sampleTime)
contact = localWorkspaceTimeseries(simOut, "f90_foot_contact", 2);
torso = localWorkspaceTimeseries(simOut, "f90_torso_state", 11);
joint = localWorkspaceTimeseries(simOut, "f90_joint_state", 12);
action = localWorkspaceTimeseries(simOut, "f90_control_action", 6);
torque = localWorkspaceTimeseries(simOut, "f90_joint_torque", 6);
position = localWorkspaceTimeseries(simOut, "f90_forward_position", 1);
power = localWorkspaceTimeseries(simOut, "f90_power", 1);
reward = localWorkspaceTimeseries(simOut, "f90_reward", 1);
done = localWorkspaceTimeseries(simOut, "f90_done", 1);

time = (0:sampleTime:stopTime)';
if time(end) < stopTime - sampleTime / 100
    time(end + 1, 1) = stopTime; %#ok<AGROW>
end
outputs = struct( ...
    "time_s", time, ...
    "foot_contact", localInterp(contact, time, "previous"), ...
    "torso_state", localInterp(torso, time, "linear"), ...
    "joint_state", localInterp(joint, time, "linear"), ...
    "control_action", localInterp(action, time, "previous"), ...
    "joint_torque", localInterp(torque, time, "previous"), ...
    "forward_position_m", localInterp(position, time, "linear"), ...
    "power_w", localInterp(power, time, "linear"), ...
    "reward", localInterp(reward, time, "previous"), ...
    "done", localInterp(done, time, "previous"));
end

function row = localFinalizeScenario(row, outputs, stopTime)
allValues = [outputs.time_s; outputs.foot_contact(:); ...
    outputs.torso_state(:); outputs.joint_state(:); ...
    outputs.control_action(:); outputs.joint_torque(:); ...
    outputs.forward_position_m(:); outputs.power_w(:); ...
    outputs.reward(:); outputs.done(:)];
row.simulation_pass = true;
row.required_evidence_pass = all(isfinite(allValues)) && ...
    numel(outputs.time_s) >= 2 && outputs.time_s(1) == 0 && ...
    outputs.time_s(end) >= stopTime - 1e-6;
row.valid = row.required_evidence_pass;
row.sample_count = numel(outputs.time_s);
row.start_time_s = outputs.time_s(1);
row.end_time_s = outputs.time_s(end);
row.outputs = outputs;
row.error = struct;
end

function audit = localStaticAudit(model)
environment = model + "/Learning Environment";
physical = environment + "/Physical Model";
jointControl = environment + "/Joint Control";
rootBus = model + "/Bus" + newline + "Creator";
unitDelay = model + "/Unit Delay";
agent = model + "/RL Agent";
dataProcessing = environment + "/Data Processing";
reward = dataProcessing + "/Calculate Reward";
done = dataProcessing + "/Check if Done1";
audit = struct( ...
    "pinned_rl_agent_present", getSimulinkBlockHandle(agent) > 0, ...
    "physical_model_present", getSimulinkBlockHandle(physical) > 0, ...
    "joint_control_present", getSimulinkBlockHandle(jointControl) > 0, ...
    "action_to_joint_control", ...
        localPortConnects(agent, 1, environment, 1), ...
    "joint_torque_to_physical_model", ...
        localPortConnects(jointControl, 1, physical, 1), ...
    "joint_state_feedback", ...
        localPortConnects(physical, 3, jointControl, 2), ...
    "observation_to_agent", ...
        localPortConnects(environment, 1, rootBus, 1) && ...
        localPortConnects(unitDelay, 1, rootBus, 2) && ...
        localPortConnects(rootBus, 1, agent, 1), ...
    "reward_to_agent", localPortConnects(environment, 2, agent, 2), ...
    "termination_to_agent", ...
        localPortConnects(environment, 3, agent, 3), ...
    "forward_position_to_termination", ...
        localPortConnects(physical, 4, dataProcessing, 1), ...
    "torso_to_reward_and_done", ...
        localPortConnects(physical, 2, dataProcessing, 2) && ...
        getSimulinkBlockHandle(reward) > 0 && ...
        getSimulinkBlockHandle(done) > 0);
values = struct2cell(audit);
audit.core_path_qualified = all(cellfun(@(value) logical(value), values));
end

function pass = localPortConnects(source, outIndex, destination, inIndex)
pass = false;
try
    sourcePorts = get_param(source, "PortHandles");
    destinationPorts = get_param(destination, "PortHandles");
    line = get_param(sourcePorts.Outport(outIndex), "Line");
    destinations = get_param(line, "DstPortHandle");
    pass = any(destinations == destinationPorts.Inport(inIndex));
catch
end
end

function series = localWorkspaceTimeseries(simOut, name, columns)
value = localGetOutput(simOut, name);
assert(isa(value, "timeseries"), "SimuVerity:F90:XROBO06:WorkspaceTap", ...
    "Required measurement tap %s is missing or not Timeseries.", name);
data = squeeze(double(value.Data));
if isvector(data), data = data(:); end
if size(data, 1) ~= numel(value.Time) && ...
        size(data, 2) == numel(value.Time)
    data = data.';
end
assert(size(data, 1) == numel(value.Time) && ...
    size(data, 2) == columns, "SimuVerity:F90:XROBO06:WorkspaceShape", ...
    "Tap %s has unexpected dimensions.", name);
series = struct( ...
    "time", double(value.Time(:)), ...
    "values", data);
end

function values = localInterp(series, time, method)
assert(~isempty(series.time) && ~isempty(series.values), ...
    "SimuVerity:F90:XROBO06:EmptySeries", "Required series is empty.");
if numel(series.time) == 1
    values = repmat(series.values(1, :), numel(time), 1);
    return
end
[uniqueTime, uniqueIndices] = unique(series.time, "stable");
uniqueValues = series.values(uniqueIndices, :);
values = interp1(uniqueTime, uniqueValues, time, method, "extrap");
end

function value = localGetOutput(simOut, name)
value = [];
try, value = simOut.get(name); catch, end
if isempty(value)
    try, value = evalin("base", name); catch, end
end
end

function row = localEmptyScenario
row = struct( ...
    "id", "", ...
    "requested_inputs", struct, ...
    "simulation_pass", false, ...
    "required_evidence_pass", false, ...
    "valid", false, ...
    "simulation_wall_clock_s", 0, ...
    "sample_count", 0, ...
    "start_time_s", 0, ...
    "end_time_s", 0, ...
    "outputs", struct, ...
    "error", struct);
end

function info = localError(ME)
info = struct("identifier", string(ME.identifier), ...
    "message", regexprep(string(ME.message), "[^\x20-\x7E]", "?"));
end

function localCloseModels(model)
try
    if bdIsLoaded(model), close_system(model, 0); end
catch
end
try
    if bdIsLoaded("sm_humanoid_walker_lib")
        close_system("sm_humanoid_walker_lib", 0);
    end
catch
end
try
    evalin("base", "clear f90_reference_agent params");
catch
end
end

function binding = localFilePresence(path)
assert(isfile(path), "SimuVerity:FileMissing", "Required file is missing: %s", path);
binding = "present";
end

function localWriteJson(path, value)
fid = fopen(path, "w");
assert(fid > 0, "SimuVerity:F90:XROBO06:JsonWrite", ...
    "Could not open JSON output: %s", path);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
bytes = unicode2native(jsonencode(value, PrettyPrint=true), "UTF-8");
fwrite(fid, bytes, "uint8");
end

function value = localNow
value = string(datetime("now", ...
    "TimeZone", "Asia/Shanghai", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ssXXX"));
end
